output-exprs.el:
archivo.subproceso.descripcion:if(
  and(
    pv!flagMarcaSubsecuenteINFONAVIT=true,
    pv!flagFlujoSubsecuente=true
  ),
  "SUBSECUENTE INFONAVIT",
  if(
    and(
      pv!flagMarcaSubsecuenteFOVISSSTE=true,
      pv!flagFlujoSubsecuente=true
    ),
    "SUBSECUENTE FOVISSSSTE",
  pv!archivo.subproceso.descripcion
)
)

archivo.subproceso.id:if(
  and(
    pv!flagMarcaSubsecuenteINFONAVIT=true,
    pv!flagFlujoSubsecuente=true
  ),
  9,
  if(
    and(
      pv!flagMarcaSubsecuenteFOVISSSTE=true,
      pv!flagFlujoSubsecuente=true
    ),
    105,
  pv!archivo_in.subproceso.id
)
)

errorServicio:if(
  a!isNullOrEmpty(pv!errorServicio),
  index(
    #"_a-0000ec60-cceb-8000-9ba6-011c48011c48_47665"(
      idInstancia_int: pp!id,
      tipoEvento_txt: "BUS"
    ),
    1,
    #"urn:appian:record-field:v1:130b4ad6-0f66-42c0-bfea-c818c5921084/1725ad41-0639-439d-8356-13b2310fead7",
    {}
  ),
  pv!errorServicio
)
